    @import url("https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap");
    * { font-family: "Poppins", sans-serif; }
    body { background: #ffffff; min-height: 100vh; margin: 0; }
    #mainContent::-webkit-scrollbar { width: 5px; }
    #mainContent::-webkit-scrollbar-track { background: #e2e8f0; border-radius: 3px; }
    #mainContent::-webkit-scrollbar-thumb { background: #059669; border-radius: 3px; }
    .fade-up { animation: fade-up .45s cubic-bezier(.23,1,.32,1) both; }
    .count { font-variant-numeric: tabular-nums; }
    .status-ring { animation: ring-pop .75s cubic-bezier(.23,1,.32,1) both; }
    .status-fill { transform-origin: left center; transform: scaleX(0); animation: fill-grow .8s cubic-bezier(.23,1,.32,1) .2s forwards; transition: width .7s cubic-bezier(.23,1,.32,1); }
    .status-segment { opacity: 0; transition: stroke-dasharray .85s cubic-bezier(.23,1,.32,1), opacity .2s ease-out; }
    .status-segment.drawn { opacity: 1; }
    @keyframes fade-up { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes ring-pop { from { opacity: 0; transform: scale(.88) rotate(-18deg); } to { opacity: 1; transform: scale(1) rotate(0); } }
    @keyframes fill-grow { from { transform: scaleX(0); } to { transform: scaleX(1); } }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; } }
