    <div class="bg-white border-t border-gray-200 flex-shrink-0 fixed bottom-0 left-0 right-0 z-20"><div class="max-w-5xl mx-auto px-4 flex justify-around py-2"><a href="./dashboard.php" class="flex flex-col items-center justify-center py-2 px-3 text-emerald-600 bg-emerald-50 transition-all" style="border-radius:3px"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="w-5 h-5"><path stroke-linecap="round" stroke-linejoin="round" d="M3.75 6A2.25 2.25 0 0 1 6 3.75h2.25A2.25 2.25 0 0 1 10.5 6v2.25c0 1.243-1.007 2.25-2.25 2.25H6a2.25 2.25 0 0 1-2.25-2.25V6ZM3.75 15.75A2.25 2.25 0 0 1 6 13.5h2.25a2.25 2.25 0 0 1 2.25 2.25V18A2.25 2.25 0 0 1 8.25 20.25H6A2.25 2.25 0 0 1 3.75 18v-2.25ZM13.5 6a2.25 2.25 0 0 1 2.25-2.25H18A2.25 2.25 0 0 1 20.25 6v2.25A2.25 2.25 0 0 1 18 10.5h-2.25a2.25 2.25 0 0 1-2.25-2.25V6ZM13.5 15.75a2.25 2.25 0 0 1 2.25-2.25H18a2.25 2.25 0 0 1 2.25 2.25V18A2.25 2.25 0 0 1 18 20.25h-2.25A2.25 2.25 0 0 1 13.5 18v-2.25Z" /></svg><span class="text-xs font-medium mt-1">Dashboard</span></a><a href="./menu.php" class="flex flex-col items-center justify-center py-2 px-3 text-gray-500 hover:text-gray-900 hover:bg-gray-50 transition-all" style="border-radius:3px"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="w-5 h-5"><path stroke-linecap="round" stroke-linejoin="round" d="M3.75 12h16.5m-16.5 3.75h16.5M3.75 19.5h16.5M5.625 4.5h12.75a1.875 1.875 0 0 1 0 3.75H5.625a1.875 1.875 0 0 1 0-3.75Z" /></svg><span class="text-xs font-medium mt-1">Menu</span></a><a href="./orders.php" class="flex flex-col items-center justify-center py-2 px-3 text-gray-500 hover:text-gray-900 hover:bg-gray-50 transition-all" style="border-radius:3px"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="w-5 h-5"><path stroke-linecap="round" stroke-linejoin="round" d="M9 12h3.75M9 15h3.75M9 18h3.75m3 .75H18a2.25 2.25 0 0 0 2.25-2.25V6.108c0-1.135-.845-2.098-1.976-2.192a48.424 48.424 0 0 0-1.123-.08m-5.801 0c-.065.21-.1.433-.1.664 0 .414.336.75.75.75h4.5a.75.75 0 0 0 .75-.75 2.25 2.25 0 0 0-.1-.664m-5.8 0A2.251 2.251 0 0 1 13.5 2.25H15c1.012 0 1.867.668 2.15 1.586m-5.8 0c-.376.023-.75.05-1.124.08C9.095 4.01 8.25 4.973 8.25 6.108V8.25m0 0H4.875c-.621 0-1.125.504-1.125 1.125v11.25c0 .621.504 1.125 1.125 1.125h9.75c.621 0 1.125-.504 1.125-1.125V9.375c0-.621-.504-1.125-1.125-1.125H8.25Z" /></svg><span class="text-xs font-medium mt-1">Orders</span></a><a href="./account.php" class="flex flex-col items-center justify-center py-2 px-3 text-gray-500 hover:text-gray-900 hover:bg-gray-50 transition-all" style="border-radius:3px"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="w-5 h-5"><path stroke-linecap="round" stroke-linejoin="round" d="M15.75 6a3.75 3.75 0 1 1-7.5 0 3.75 3.75 0 0 1 7.5 0ZM4.501 20.118a7.5 7.5 0 0 1 14.998 0A17.933 17.933 0 0 1 12 21.75c-2.676 0-5.216-.584-7.499-1.632Z" /></svg><span class="text-xs font-medium mt-1">Account</span></a></div></div>
  </div>

  <div id="toast" class="hidden fixed left-1/2 -translate-x-1/2 bottom-20 z-40 px-4 py-2 bg-gray-800 text-white text-[11px] font-medium rounded-md shadow-lg"></div>

  <script>
    const toast = message => { const element = document.getElementById("toast"); element.textContent = message; element.classList.remove("hidden"); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => element.classList.add("hidden"), 2200); };
    const formatNumber = value => Number(value).toLocaleString("en-PH");
    const animateCounts = () => document.querySelectorAll("[data-count]").forEach(element => { const end = Number(element.dataset.count); const prefix = element.dataset.prefix || ""; const started = performance.now(); const tick = now => { const progress = Math.min((now - started) / 650, 1); const eased = 1 - Math.pow(1 - progress, 3); element.textContent = prefix + formatNumber(Math.round(end * eased)); if (progress < 1) requestAnimationFrame(tick); }; requestAnimationFrame(tick); });
    const statusData = { delivery: { total: 74, statuses: [{ key: "pending", label: "Pending", count: 6, color: "#f59e0b" }, { key: "preparing", label: "Preparing", count: 11, color: "#fb923c" }, { key: "ready_for_dispatch", label: "Ready for dispatch", count: 17, color: "#38bdf8" }, { key: "collected", label: "Collected", count: 14, color: "#818cf8" }, { key: "out_for_delivery", label: "Out for delivery", count: 9, color: "#a78bfa" }, { key: "delivered", label: "Delivered", count: 13, color: "#10b981" }, { key: "cancelled", label: "Cancelled", count: 4, color: "#f87171" }] }, pickup: { total: 112, statuses: [{ key: "pending", label: "Pending", count: 6, color: "#f59e0b" }, { key: "preparing", label: "Preparing", count: 17, color: "#fb923c" }, { key: "ready_for_pickup", label: "Ready for pickup", count: 17, color: "#38bdf8" }, { key: "completed", label: "Completed", count: 68, color: "#10b981" }, { key: "cancelled", label: "Cancelled", count: 4, color: "#f87171" }] } };
    const chartCircumference = 2 * Math.PI * 43;
    const statusAngles = data => data.statuses.map(status => status.count / data.total * 360);
    const formatStatusLabel = key => key.replaceAll("_", " ").replace(/\b\w/g, letter => letter.toUpperCase());
    const updateStatus = channel => { const data = statusData[channel]; const segments = document.getElementById("statusSegments"); const legend = document.getElementById("statusLegend"); const angles = statusAngles(data); let offset = 0; segments.innerHTML = data.statuses.map((status, index) => { const length = status.count / data.total * chartCircumference; const dashOffset = chartCircumference - offset; offset += length; return `<circle class="status-segment" cx="60" cy="60" r="43" fill="none" stroke="${status.color}" stroke-width="12" stroke-linecap="butt" stroke-dasharray="0 ${chartCircumference}" stroke-dashoffset="${dashOffset}"></circle>`; }).join(""); legend.innerHTML = data.statuses.map(status => `<div><div class="flex items-center justify-between gap-2"><div class="flex items-center gap-2 min-w-0"><span class="w-2.5 h-2.5 rounded-full shrink-0" style="background:${status.color}"></span><span class="text-[10px] sm:text-[11px] font-semibold text-gray-700 truncate">${formatStatusLabel(status.key)}</span></div><span class="text-[10px] sm:text-[11px] font-bold text-gray-800">${status.count}</span></div><div class="h-1 bg-gray-100 rounded-full overflow-hidden mt-1"><div class="status-fill h-full rounded-full" style="background:${status.color};width:${status.count / data.total * 100}%"></div></div></div>`).join(""); document.getElementById("statusTotal").textContent = data.total; document.getElementById("statusSubtitle").textContent = `${data.total} ${channel} orders today`; requestAnimationFrame(() => { segments.querySelectorAll(".status-segment").forEach((segment, index) => { const length = data.statuses[index].count / data.total * chartCircumference; segment.style.strokeDasharray = `${length} ${chartCircumference - length}`; segment.classList.add("drawn"); }); }); document.getElementById("statusDelivery").className = channel === "delivery" ? "status-channel active px-2.5 py-1.5 border text-white bg-emerald-600 border-emerald-600 text-[10px] font-semibold rounded-[4px] transition-all" : "status-channel px-2.5 py-1.5 border text-gray-500 bg-white border-gray-200 text-[10px] font-semibold rounded-[4px] transition-all"; document.getElementById("statusPickup").className = channel === "pickup" ? "status-channel active px-2.5 py-1.5 border text-white bg-emerald-600 border-emerald-600 text-[10px] font-semibold rounded-[4px] transition-all" : "status-channel px-2.5 py-1.5 border text-gray-500 bg-white border-gray-200 text-[10px] font-semibold rounded-[4px] transition-all"; };
    updateStatus("delivery");
    const toggle = document.getElementById("stallToggle");
    const statusLabel = document.getElementById("stallStatusLabel");
    const statusDot = document.getElementById("stallStatusDot");
    document.getElementById("statusDelivery").addEventListener("click", () => updateStatus("delivery"));
    document.getElementById("statusPickup").addEventListener("click", () => updateStatus("pickup"));
    toggle.addEventListener("change", () => { const open = toggle.checked; statusLabel.textContent = open ? "Open — visible on customer home" : "Closed — hidden from customer home"; statusDot.className = open ? "w-2.5 h-2.5 rounded-full bg-emerald-500 shrink-0" : "w-2.5 h-2.5 rounded-full bg-gray-300 shrink-0"; toast(open ? "Stall is now visible to customers" : "Stall is now hidden from customers"); });
    document.getElementById("notifBtn").addEventListener("click", () => document.getElementById("notifDropdown").classList.toggle("hidden"));
    document.getElementById("markRead").addEventListener("click", () => { document.getElementById("notifDropdown").classList.add("hidden"); toast("Notifications marked as read"); });
    document.getElementById("messageBtn").addEventListener("click", () => toast("No new messages"));
    document.getElementById("accountButton").addEventListener("click", () => toast("Account page is ready to connect"));
    document.querySelectorAll("[data-toast]").forEach(button => button.addEventListener("click", () => toast(button.dataset.toast)));
    animateCounts();
  </script>
</body>
</html>
